 {
  if(square<0||square>3)throw new ArgumentOutOfRangeException("square");var scene=SceneManager.GetActiveScene();if(scene.isDirty||scene.path!="Assets/Scenes/World/Enroth.unity")throw new Exception("Need saved Enroth");string rootName="North Canonical Woodland Transition "+square+" 20261007";if(GameObject.Find(rootName))throw new Exception("Already saved");
