  var old=original.GetAlphamaps(0,0,original.alphamapWidth,original.alphamapHeight);var alpha=new float[old.GetLength(0),old.GetLength(1),layers.Count];for(int z=0;z<old.GetLength(0);z++)for(int x=0;x<old.GetLength(1);x++)for(int l=0;l<old.GetLength(2);l++)alpha[z,x,l]=old[z,x,l];int band=Mathf.CeilToInt(92f/512*old.GetLength(0));
