   root=new GameObject(rootName);root.hideFlags=HideFlags.HideAndDontSave;var mature=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TempDragonTemplate/TracePine.prefab");var young=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TempDragonTemplate/TraceYoungPine.prefab");if(!mature||!young)throw new Exception("Production conifers missing");var random=new System.Random(84001+square);var occupied=UnityEngine.Object.FindObjectsByType<Transform>().Where(t=>t.name.StartsWith("AuthoredPine_")||t.name.StartsWith("SourceTree_")||t.name.StartsWith("Eco_")).Select(t=>new Vector2(t.position.x,t.position.z)).ToList();
